    completedMeals:'Comidas registradas',weeklyConsistency:'Constancia semanal',todayFeel:'¿Cómo te sentiste hoy?',feelGreat:'Muy bien',feelGood:'Bien',feelOkay:'Regular',feelTough:'Un poco difícil',feelReset:'Necesito retomar',saveReflection:'Guardar reflexión',
